import sympy as s, json
spec = TASK["public"]["specification"]
x = s.symbols("x0:10")
expr = s.SOPform(x, [row for row, y in zip(spec["inputs"], spec["outputs"]) if y == 1])
terms = list(s.Or.make_args(expr))
patch = []
def put(t, idx, val):
    if val:
        patch.append({"op":"set", "tensor":t, "index":idx, "value":float(val)})

for i in range(10):
    put("w0", [i,i], 1)
    for layer in range(1,4):
        put(f"w{layer}", [i,i], 1)

for k,term in enumerate(terms):
    j=10+k
    literals=s.And.make_args(term)
    npos=0
    for lit in literals:
        if lit.func == s.Not:
            put("w0", [j,x.index(lit.args[0])], -1)
        else:
            put("w0", [j,x.index(lit)], 1)
            npos+=1
    put("b0",[j],1-npos)
    for layer in range(1,4):
        put(f"w{layer}",[j,j],1)
    put("out",[1,j],1)
put("bias",[0],0.5)
sub={"patch":patch}
print(check_submission(sub))
with open("/work/submission.json","w") as f:
    json.dump(sub,f)
